			function grdColumnAdd(header, rngId) {
			    
			    var grdList = app.lookup("grdList");
			    var dataSet = grdList.dataSet;
			    
			    var grdCellInd = grdList.header.getCellIndices();
			    var grdColCnt = grdCellInd.length;
			    
			    dataSet.addColumn(new cpr.data.header.DataHeader("col" + rngId));
			    
			    grdList.addColumn({
			        columnLayout: [{
			            width: "40px"
			        }],
			        header: [{
			            constraint: {
			                rowIndex: 0,
			                colIndex: grdColCnt,
			                colSpan: 1,
			                rowSpan: 1
			            },
			            configurator: function(configurator) {
			                
			                configurator.control = (function() {
			                    var outPut_1 = new cpr.controls.Output("");
			                    outPut_1.userAttr("colIdx", String(grdColCnt));
			                    outPut_1.text = header;
			                    outPut_1.style.css({
			                        "text-align": "center"
			                    });
			                    return outPut_1;
			                })();
			            }
			        }],
			        detail: [{
			            constraint: {
			                rowIndex: 0,
			                colIndex: grdColCnt
			            },
			            configurator: function(cell) {
			                cell.columnName = "col" + rngId;
			                cell.control = (function() {
			                    var outPut_1 = new cpr.controls.Output("");
			                    outPut_1.style.css({
			                        "text-align": "center"
			                    });
			                    outPut_1.bind("value").toDataColumn("col" + rngId);
			                    return outPut_1;
			                })();
			                cell.controlConstraint = {};
			            }
			        }]
			        
			    });
			}

			function doMsgClick(e) {
			    var obj = e.control;
			    for (var i = 1; i <= 4; i++) {
			        app.lookup('grpTitle' + i).style.setClasses('card-title hidden');
			        app.lookup('grpTitle' + i + 'Grid').visible = false;
			    }
			    obj.style.setClasses('card-title');
			    app.lookup(obj.id + 'Grid').visible = true;
			}

