			/*
			 * 지역별 실적현황 데이터 셋팅
			 */
			function orgnResultSet(){
			    var dsRgnList = app.lookup("dsRgnList");
			    var dsList = app.lookup("dsList");
			    var dsList3 = app.lookup("dsList3");
			    dsList3.clearData();
			    var allRegSum = 0; // 신규전체합계
			    var allPrgrsSum = 0; // 진행전체합계
			    var allTrmnSum = 0; // 종료전체합계
			    var allSum = 0; //전체합계
			    var allCompleteRate = 0; // 전체완료율
			    
			    for(var i = 0; i < dsRgnList.getRowCount(); i++){
			        var rgnNm = dsRgnList.getValue(i, "ADDTNG_MNG_VALUE1");
			        var rgnCd = dsRgnList.getValue(i, "ADDTNG_MNG_VALUE2");
			        var sColNm = "PRFMNC_";
			        var eColNm = "_NOCS";
			        var regColNm = sColNm + rgnCd + "_REG" + eColNm;
			        var prgrsColNm = sColNm + rgnCd + "_PRGRS" + eColNm;
			        var trmnColNm = sColNm + rgnCd + "_TRMN" + eColNm;
			        var regCnt = ValueUtil.fixNumber(dsList.getValue(0, regColNm));
			        var prgrsCnt = ValueUtil.fixNumber(dsList.getValue(0, prgrsColNm));
			        var trmnCnt = ValueUtil.fixNumber(dsList.getValue(0, trmnColNm));
			        var allCnt = ValueUtil.fixNumber(regCnt + prgrsCnt + trmnCnt);
			        
			        allRegSum = allRegSum + regCnt;
			        allPrgrsSum = allPrgrsSum + prgrsCnt;
			        allTrmnSum = allTrmnSum + trmnCnt;
			        
			        var completeRate = 0;
			        if(allCnt > 0 ){
			            completeRate = Math.round(trmnCnt / allCnt * 100);
			        }

			        var newRowData = {
			            "CITY_CD": rgnCd,
			            "CITY_NM": rgnNm,
			            "CITY_CNT0": regCnt, // 신규 건수
			            "CITY_CNT1": prgrsCnt, // 진행 건수
			            "CITY_CNT2": trmnCnt, // 종료 건수
			            "CITY_CNT3": completeRate // 완료율
			        };
			        dsList3.insertRowData(i, true, newRowData);
			    }
			    dsList3.setSort("CITY_NM");
			    var allCompleteRate = 0;
			    allSum = ValueUtil.fixNumber(allRegSum + allPrgrsSum + allTrmnSum);
			    if(allSum > 0){
			        allCompleteRate = Math.round(allTrmnSum / allSum * 100);
			    }
			    var allCntData = {
			        "CITY_CD": "total",
			        "CITY_NM": "전체",
			        "CITY_CNT0": allRegSum, // 신규 건수
			        "CITY_CNT1": allPrgrsSum, // 진행 건수
			        "CITY_CNT2": allTrmnSum, // 종료 건수
			        "CITY_CNT3": allCompleteRate // 완료율
			    }
			    dsList3.insertRowData(0, false, allCntData);
			    dsList3.setRowStateAll(cpr.data.tabledata.RowState.UNCHANGED );
			    app.lookup("grdList").selectRows(0);
			}

